 void RefreshDeviceRail(){if(railDevices==null)return;railDevices.Children.Clear();railDots.Clear();foreach(var server in config.Servers){var selected=active!=null&&ArchiveStore.Key(active)==ArchiveStore.Key(server);var content=new Grid{Margin=new Thickness(11,12,11,12)};content.ColumnDefinitions.Add(new ColumnDefinition{Width=GridLength.Auto});content.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(1,GridUnitType.Star)});content.ColumnDefinitions.Add(new ColumnDefinition{Width=GridLength.Auto});var icon=new IconView(server.IsLocal?"Laptop":"Server",22,selected?Theme.Accent:Theme.Muted);content.Children.Add(icon);var text=new StackPanel{Margin=new Thickness(11,0,8,0),Visibility=railCompact?Visibility.Collapsed:Visibility.Visible};text.Children.Add(Theme.Text(server.Name,16,selected?Theme.Accent:Theme.Ink,false,true));var sub=Theme.Text(server.IsLocal?"Windows 工作站":server.Host,13,Theme.Muted);sub.Margin=new Thickness(0,3,0,0);text.Children.Add(sub);Grid.SetColumn(text,1);content.Children.Add(text);var reading=capture==null?null:capture.Latest(server);var color=reading==null?Theme.Muted:string.IsNullOrEmpty(reading.Metrics.Error)?Theme.Green:Theme.Amber;var dot=new Border{Background=color,Width=5,Height=5,CornerRadius=new CornerRadius(3),VerticalAlignment=VerticalAlignment.Center,Visibility=railCompact?Visibility.Collapsed:Visibility.Visible};railDots[ArchiveStore.Key(server)]=dot;Grid.SetColumn(dot,2);content.Children.Add(dot);var button=Theme.Action("",()=>ChooseServer(server));button.Content=content;button.HorizontalContentAlignment=HorizontalAlignment.Stretch;button.Padding=new Thickness(0);button.MinHeight=railCompact?54:76;button.Margin=new Thickness(0,0,0,8);button.Background=selected?Theme.AccentSoft:Brushes.Transparent;button.ToolTip=server.IsLocal?"本机设备":server.User+"@"+server.Host+":"+server.Port;railDevices.Children.Add(button);}if(shellHeading!=null)shellHeading.Text=active==null?"AQ Server":active.Name;UpdateShellReading(lastStatus??last);}
 void UpdateShellReading(Metrics reading){foreach(var device in config.Servers){Border dot;if(!railDots.TryGetValue(ArchiveStore.Key(device),out dot))continue;var sample=capture==null?null:capture.Latest(device);var metric=sample==null?(active!=null&&ArchiveStore.Key(active)==ArchiveStore.Key(device)?reading:null):sample.Metrics;dot.Background=metric==null?Theme.Muted:string.IsNullOrEmpty(metric.Error)?Theme.Green:Theme.Amber;}if(active==null)return;bool error=reading!=null&&!string.IsNullOrEmpty(reading.Error);if(shellAddress!=null){shellAddress.Text=error?(lastGood==null?"连接中":"重连中"):active.IsLocal?"● 本机":"● SSH 已连接";shellAddress.Foreground=error?Theme.Amber:Theme.Green;}var info=lastGood==null?null:lastGood.Hardware;if(railSystem!=null){railSystem.Text=info!=null?info.OperatingSystem:"读取中";railSystem.ToolTip=railSystem.Text;railCpu.Text=lastGood==null?"读取中":lastGood.Cores+" 逻辑处理器";railCpu.ToolTip=info==null?null:info.CpuModel;railGpu.Text=lastGood==null?"读取中":lastGood.Gpus.Count==0?"未检测到":lastGood.Gpus.Select(x=>x.Name).Distinct().Count()==1?lastGood.Gpus.Count+" × "+ShortGpu(lastGood.Gpus[0].Name):lastGood.Gpus.Count+" 张显卡";railGpu.ToolTip=lastGood==null?null:string.Join("\n",lastGood.Gpus.Select(x=>"GPU "+x.Index+" · "+x.Name));}if(footerLive!=null){footerLive.Text=error?"● 重连中":"● 持续存档";footerLive.Foreground=error?Theme.Amber:Theme.Green;}if(footerCpu!=null){footerCpu.Data=History;footerCpu.Refresh();}if(lastGood==null){cpuDetail.Text="—";gpuDetail.Text="—";footerGpu.Set(new List<Gpu>());footerMemory.Value=0;NumericMotion.Text(MemoryValue,"—");memoryDetail.Text="";}if(lastGood!=null){cpuDetail.Text=lastGood.Cores+" 线程";gpuDetail.Text=lastGood.Gpus.Count==0?"无显卡":lastGood.Gpus.Count+" 张显卡";DiskValue.ToolTip=lastGood.Gpus.Count==0?"未检测到 NVIDIA 显卡":"GPU 平均利用率";footerGpu.Set(lastGood.Gpus);footerMemory.Value=ResourceSample.MemoryPercent(lastGood.Mem);var values=System.Text.RegularExpressions.Regex.Matches(lastGood.Mem??"",@"[0-9.]+");if(values.Count>=2){NumericMotion.Text(MemoryValue,(GpuCard.Number(values[0].Value)/1024).ToString("0.0")+" GiB");memoryDetail.Text=" / "+(GpuCard.Number(values[1].Value)/1024).ToString("0.0")+" GiB";}}}
 static string ShortGpu(string name){return (name??"").Replace("NVIDIA GeForce ","").Replace("NVIDIA ","");}

 string HealthKey(Server s){return ArchiveStore.Key(s)+"|"+s.KeyPath;}
 string ConnectionLabel(){if(active!=null&&active.IsLocal)return "本机";return healthResult!=null&&healthResult.Success&&active!=null&&healthKey==HealthKey(active)?healthResult.Milliseconds+" ms":"已连接";}
 internal void RequestConnectionHealth(bool force=false){if((testMode&&!force)||active==null||healthBusy||exitAllowed)return;var device=active.Copy();string key=HealthKey(device);if(healthKey==key&&DateTime.UtcNow<nextHealth)return;healthBusy=true;Task.Run(()=>ConnectionProbe.Run(device)).ContinueWith(job=>{if(Dispatcher.HasShutdownStarted)return;Dispatcher.BeginInvoke((System.Action)(()=>{healthBusy=false;if(exitAllowed||active==null||HealthKey(active)!=key)return;healthKey=key;healthResult=job.IsFaulted?new ConnectionResult{Success=false,Message="连接检测失败"}:job.Result;nextHealth=DateTime.UtcNow.AddSeconds(30);if(healthResult.Success&&lastGood!=null&&Connection.Text!="重连中"){Connection.Text=ConnectionLabel();Connection.Foreground=Theme.Green;}Connection.ToolTip=healthResult.Details;}));});}
